										class="kt-row-column-wrap kt-has-2-columns kt-gutter-default kt-v-gutter-default kt-row-valign-top kt-row-layout-equal kt-tab-layout-inherit kt-m-colapse-left-to-right kt-mobile-layout-row">
										<div class="wp-block-kadence-column inner-column-1 kadence-column_523a36-3a">
											<div class="kt-inside-inner-col">
												<figure class="wp-block-image size-large"><img loading="lazy"
														decoding="async" width="1024" height="768"
														src="./Jurassic Days_ Dino Statue Driving Tour_files/Seymour-Sparklesaurus-aka-Sparky.jpeg"
														alt="Seymour-Sparklesaurus-aka-Sparky" class="wp-image-14161"
														srcset="https://carnegiemnh.org/wp-content/uploads/2020/07/Seymour-Sparklesaurus-aka-Sparky.jpeg 1024w, https://carnegiemnh.org/wp-content/uploads/2020/07/Seymour-Sparklesaurus-aka-Sparky-300x225.jpeg 300w, https://carnegiemnh.org/wp-content/uploads/2020/07/Seymour-Sparklesaurus-aka-Sparky-768x576.jpeg 768w"
														sizes="auto, (max-width: 1024px) 100vw, 1024px"></figure>
											</div>
										</div>



										<div class="wp-block-kadence-column inner-column-2 kadence-column_a1d39e-48">
											<div class="kt-inside-inner-col">
												<p><strong>Tenth Stop:</strong> Seymour Sparklesaurus
													“Sparky”<br><strong>Coordinates:</strong> 40.448522, -79.953038</p>



												<p>Located at and designed by the Western Pennsylvania School for Blind
													Children, Sparky features handprints and an oversized braille
													message: “stegosaurus.”</p>
											</div>
										</div>
									</div>
								</div>
							</div>



							<div class="wp-block-kadence-rowlayout alignnone">
								<div id="kt-layout-id_2c1f40-57" class="kt-row-layout-inner kt-layout-id_2c1f40-57">
